        /** A count string: nq_store_account_n($t, 'reorderAdded', 3) gives "3 items added to your cart." */
        function nq_store_account_n(array $t, string $key, int|float $n): string
        {
            $text = ($n == 1 && isset($t[$key . 'One'])) ? $t[$key . 'One'] : $t[$key];

            return str_replace('{n}', (string) $n, $text);
        }
